package Tasks;

public class ifelseifladdertask4 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=4,b=2,c=7;
		if(a<b && a<c) {
			System.out.println("smallest a");
		}
		else if(b<a && b<c) {
			System.out.println("smallest b");
		}
		else {
			System.out.println("smallest c");
		}

	}

}
